/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `getDashboardActualConsumptionList`(VAR_PROGRAM_ID INT)
BEGIN

SELECT COUNT(DISTINCT(ppu.PROGRAM_PLANNING_UNIT_ID)) AS PU_COUNT, COUNT(DISTINCT(ppu.PROGRAM_PLANNING_UNIT_ID))-COUNT(DISTINCT CASE WHEN (prr.PROBLEM_STATUS_ID = 1 AND (prr.REALM_PROBLEM_ID = 1 OR prr.REALM_PROBLEM_ID = 24)) THEN prr.DATA3 END) AS GOOD_COUNT
FROM rm_problem_report prr 
LEFT JOIN vw_planning_unit pu ON prr.DATA3=pu.PLANNING_UNIT_ID 
LEFT JOIN vw_program prog ON prr.PROGRAM_ID=prog.PROGRAM_ID 
LEFT JOIN rm_program_planning_unit ppu ON ppu.PROGRAM_ID=prog.PROGRAM_ID AND ppu.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID                  
WHERE prr.PROGRAM_ID=VAR_PROGRAM_ID AND prr.VERSION_ID<=prog.CURRENT_VERSION_ID AND pu.ACTIVE AND ppu.ACTIVE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `getDashboardActualConsumptionListForLoadProgram` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `getDashboardActualConsumptionListForLoadProgram`(VAR_PROGRAM_ID INT, VAR_CUR_DATE DATE)
BEGIN

SET @stopDate = CONCAT(SUBSTRING(VAR_CUR_DATE,1,7),"-01");
    SET @startDate = DATE_SUB(@stopDate, INTERVAL 6 MONTH);
    SELECT p.CURRENT_VERSION_ID into @versionId FROM rm_program p WHERE p.PROGRAM_ID=VAR_PROGRAM_ID;
    SELECT COUNT(pr.REGION_ID) into @regionCount FROM rm_program_region pr LEFT JOIN rm_region r ON pr.REGION_ID=r.REGION_ID WHERE pr.PROGRAM_ID=VAR_PROGRAM_ID AND pr.ACTIVE AND r.ACTIVE;
    
    SELECT pu.PLANNING_UNIT_ID, mn.`MONTH` `CONSUMPTION_DATE` , IF(c1.ACTUAL_COUNT IS NULL, NULL, IF(c1.ACTUAL_COUNT=@regionCount, 1, 0)) `ACTUAL_COUNT`
    FROM vw_program p 
    LEFT JOIN rm_program_planning_unit ppu ON ppu.PROGRAM_ID=VAR_PROGRAM_ID AND ppu.ACTIVE
    LEFT JOIN vw_planning_unit pu ON ppu.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID AND pu.ACTIVE
    LEFT JOIN mn ON mn.MONTH BETWEEN @startDate and @stopDate
    LEFT JOIN (
        SELECT 
            ct.PLANNING_UNIT_ID, ct.CONSUMPTION_DATE, SUM(IF(ct.CONSUMPTION_QTY IS NOT NULL, 1, 0)) `ACTUAL_COUNT` 
        FROM (SELECT c.PROGRAM_ID, ct.CONSUMPTION_ID, MAX(ct.VERSION_ID) MAX_VERSION_ID FROM rm_consumption c LEFT JOIN rm_consumption_trans ct ON c.CONSUMPTION_ID=ct.CONSUMPTION_ID WHERE ct.VERSION_ID<=@versionId AND c.PROGRAM_ID=VAR_PROGRAM_ID GROUP BY ct.CONSUMPTION_ID) tc
        LEFT JOIN rm_consumption cons ON tc.CONSUMPTION_ID=cons.CONSUMPTION_ID
        LEFT JOIN rm_consumption_trans ct ON tc.CONSUMPTION_ID=ct.CONSUMPTION_ID AND tc.MAX_VERSION_ID=ct.VERSION_ID
        WHERE ct.ACTIVE AND ct.ACTUAL_FLAG=1 AND ct.CONSUMPTION_DATE BETWEEN @startDate and @stopDate
        GROUP BY ct.PLANNING_UNIT_ID, ct.CONSUMPTION_DATE
    ) c1 ON pu.PLANNING_UNIT_ID=c1.PLANNING_UNIT_ID AND mn.MONTH=c1.CONSUMPTION_DATE
    WHERE p.PROGRAM_ID=VAR_PROGRAM_ID
    ORDER BY pu.PLANNING_UNIT_ID, mn.MONTH DESC;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `getDashboardExpiriesList` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `getDashboardExpiriesList`(VAR_START_DATE DATE, VAR_STOP_DATE DATE, VAR_PROGRAM_ID INT, VAR_VERSION_ID INT)
BEGIN

    IF VAR_VERSION_ID = -1 THEN
        SELECT p.CURRENT_VERSION_ID INTO @versionId FROM rm_program p WHERE p.PROGRAM_ID=VAR_PROGRAM_ID;
    ELSE
        SET @versionId = VAR_VERSION_ID;
    END IF;

    SELECT p1.*, st.`RATE` 
    FROM (
        SELECT 
            p.PROGRAM_ID, pu.PLANNING_UNIT_ID, pu.LABEL_ID, pu.LABEL_EN, pu.LABEL_FR, pu.LABEL_SP, pu.LABEL_PR, 
            b.BATCH_ID, b.BATCH_NO, b.AUTO_GENERATED, spb.EXPIRY_DATE, SUM(spb.EXPIRED_STOCK) `EXPIRED_STOCK` 
        FROM vw_program p 
        LEFT JOIN rm_program_planning_unit ppu ON p.PROGRAM_ID=ppu.PROGRAM_ID AND ppu.ACTIVE 
        LEFT JOIN vw_planning_unit pu ON ppu.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID AND pu.ACTIVE 
        LEFT JOIN rm_supply_plan_batch_qty spb ON p.PROGRAM_ID=spb.PROGRAM_ID AND spb.VERSION_ID=@versionId AND spb.TRANS_DATE BETWEEN VAR_START_DATE and VAR_STOP_DATE AND pu.PLANNING_UNIT_ID=spb.PLANNING_UNIT_ID 
        LEFT JOIN rm_batch_info b ON spb.BATCH_ID=b.BATCH_ID 
        WHERE p.PROGRAM_ID=VAR_PROGRAM_ID AND spb.TRANS_DATE BETWEEN VAR_START_DATE and VAR_STOP_DATE AND spb.EXPIRED_STOCK>0 
        GROUP BY spb.PLANNING_UNIT_ID, spb.BATCH_ID
    ) p1 
    LEFT JOIN ( 
            SELECT 
                s.SHIPMENT_ID, MAX(st.VERSION_ID) MAX_VERSION_ID, s.CONVERSION_RATE_TO_USD, s.PROGRAM_ID 
            FROM rm_shipment s 
            LEFT JOIN rm_shipment_trans st ON s.SHIPMENT_ID=st.SHIPMENT_ID 
            WHERE 
                s.PROGRAM_ID=VAR_PROGRAM_ID
                AND st.VERSION_ID<=@versionId
                AND st.SHIPMENT_TRANS_ID IS NOT NULL 
            GROUP BY s.SHIPMENT_ID 
        ) AS s ON s.PROGRAM_ID=p1.PROGRAM_ID
    LEFT JOIN rm_shipment s1 ON s.SHIPMENT_ID=s1.SHIPMENT_ID 
    LEFT JOIN rm_shipment_trans st ON s.SHIPMENT_ID=st.SHIPMENT_ID AND s.MAX_VERSION_ID=st.VERSION_ID 
    LEFT JOIN rm_shipment_trans_batch_info stbi ON stbi.SHIPMENT_TRANS_ID=st.SHIPMENT_TRANS_ID and stbi.BATCH_ID=p1.BATCH_ID 
    WHERE stbi.BATCH_ID IS NOT NULL;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `getDashboardForecastConsumptionProblems` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `getDashboardForecastConsumptionProblems`(VAR_PROGRAM_ID INT)
BEGIN

SELECT COUNT(DISTINCT(ppu.PROGRAM_PLANNING_UNIT_ID)) AS PU_COUNT, COUNT(DISTINCT(ppu.PROGRAM_PLANNING_UNIT_ID))-COUNT(DISTINCT CASE WHEN (prr.PROBLEM_STATUS_ID = 1 AND prr.REALM_PROBLEM_ID = 8) THEN prr.DATA3 END) AS GOOD_COUNT
FROM rm_problem_report prr 
LEFT JOIN vw_planning_unit pu ON prr.DATA3=pu.PLANNING_UNIT_ID 
LEFT JOIN vw_program prog ON prr.PROGRAM_ID=prog.PROGRAM_ID 
LEFT JOIN rm_program_planning_unit ppu ON ppu.PROGRAM_ID=prog.PROGRAM_ID AND ppu.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID                  
WHERE prr.PROGRAM_ID=VAR_PROGRAM_ID AND prr.VERSION_ID<=prog.CURRENT_VERSION_ID AND pu.ACTIVE AND ppu.ACTIVE;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `getDashboardForecastConsumptionProblemsForLoadProgram` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `getDashboardForecastConsumptionProblemsForLoadProgram`(VAR_PROGRAM_ID INT, VAR_VERSION_ID INT, VAR_CUR_DATE DATE)
BEGIN

    SET @varStartDate = VAR_CUR_DATE;
    SET @varStopDate = DATE_ADD(@varStartDate, INTERVAL 18 MONTH);
    SELECT COUNT(*) into @regionCount FROM rm_program_region pr LEFT JOIN rm_region r ON pr.REGION_ID=r.REGION_ID where pr.PROGRAM_ID=VAR_PROGRAM_ID AND pr.ACTIVE AND r.ACTIVE;
    
    SELECT 
        ct.PLANNING_UNIT_ID, 
        19*@regionCount `REQUIRED_COUNT`,
        SUM(IF(ct.ACTUAL_FLAG=0, IF(ct.CONSUMPTION_QTY is not null, 1, 0), 0)) `FORECAST_COUNT`
    FROM (
        SELECT ct.CONSUMPTION_ID, MAX(ct.VERSION_ID) MAX_VERSION_ID 
        FROM rm_consumption c 
        LEFT JOIN rm_consumption_trans ct ON c.CONSUMPTION_ID=ct.CONSUMPTION_ID 
        WHERE ct.VERSION_ID<=VAR_VERSION_ID AND c.PROGRAM_ID=VAR_PROGRAM_ID 
        GROUP BY ct.CONSUMPTION_ID
    ) tc 
    LEFT JOIN rm_consumption cons ON tc.CONSUMPTION_ID=cons.CONSUMPTION_ID
    LEFT JOIN rm_consumption_trans ct ON tc.CONSUMPTION_ID=ct.CONSUMPTION_ID AND tc.MAX_VERSION_ID=ct.VERSION_ID
    LEFT JOIN vw_planning_unit pu ON ct.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID
    LEFT JOIN rm_program_planning_unit ppu ON ppu.PROGRAM_ID=cons.PROGRAM_ID AND ppu.PLANNING_UNIT_ID=ct.PLANNING_UNIT_ID
    WHERE ppu.ACTIVE AND pu.ACTIVE AND ct.ACTIVE AND ct.CONSUMPTION_DATE BETWEEN @varStartDate and @varStopDate
    GROUP BY ct.PLANNING_UNIT_ID;
END ;;
DELIMITER ;
