/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `globalConsumption`(VAR_USER_ID INT(10), VAR_REALM_ID INT(10), VAR_REALM_COUNTRY_IDS TEXT, VAR_EQUIVALENCY_UNIT_ID INT(10), VAR_PROGRAM_IDS TEXT, VAR_VERSION_ID INT(10), VAR_PLANNING_UNIT_IDS TEXT, VAR_START_DATE DATE, VAR_STOP_DATE DATE, VAR_VIEW_BY INT(10))
BEGIN
    
    
    
	
    
    
    
    
    
    
    
    
    
	
    DECLARE curRealmCountryId INT;
    DECLARE curHealthAreaId INT;
    DECLARE curOrganisationId INT;
    DECLARE curProgramId INT;
    DECLARE done INT DEFAULT FALSE;
    DECLARE cursor_acl CURSOR FOR SELECT acl.REALM_COUNTRY_ID, acl.HEALTH_AREA_ID, acl.ORGANISATION_ID, acl.PROGRAM_ID FROM us_user_acl acl WHERE acl.USER_ID=VAR_USER_ID;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = TRUE;
    
    SET @aclSqlString = CONCAT("       AND (FALSE ");
    OPEN cursor_acl;
	read_loop: LOOP
        FETCH cursor_acl INTO curRealmCountryId, curHealthAreaId, curOrganisationId, curProgramId;
        IF done THEN
            LEAVE read_loop;
        END IF;
        
        SET @aclSqlString = CONCAT(@aclSqlString,"       OR (");
        SET @aclSqlString = CONCAT(@aclSqlString,"           (p.PROGRAM_ID IS NULL OR ",IFNULL(curRealmCountryId,-1),"=-1 OR p.REALM_COUNTRY_ID=",IFNULL(curRealmCountryId,-1),")");
        SET @aclSqlString = CONCAT(@aclSqlString,"       AND (p.PROGRAM_ID IS NULL OR ",IFNULL(curHealthAreaId,-1)  ,"=-1 OR FIND_IN_SET(",IFNULL(curHealthAreaId,-1),",p.HEALTH_AREA_ID))");
        SET @aclSqlString = CONCAT(@aclSqlString,"       AND (p.PROGRAM_ID IS NULL OR ",IFNULL(curOrganisationId,-1),"=-1 OR p.ORGANISATION_ID=" ,IFNULL(curOrganisationId,-1),")");
        SET @aclSqlString = CONCAT(@aclSqlString,"       AND (p.PROGRAM_ID IS NULL OR ",IFNULL(curProgramId,-1)     ,"=-1 OR p.PROGRAM_ID="      ,IFNULL(curProgramId,-1)     ,")");
        SET @aclSqlString = CONCAT(@aclSqlString,"       )");
    END LOOP;
    CLOSE cursor_acl;
    SET @aclSqlString = CONCAT(@aclSqlString, ") ");
    
    SET @varProgramIds = VAR_PROGRAM_IDS;
    SET @varVersionId = VAR_VERSION_ID;
    SET @varRealmCountryIds = VAR_REALM_COUNTRY_IDS;
    SET @varStartDate = VAR_START_DATE;
    SET @varStopDate = VAR_STOP_DATE;
    SET @varRealmId = VAR_REALM_ID;
    SET @varViewBy = VAR_VIEW_BY;
    SET @varEquivalencyUnitId = VAR_EQUIVALENCY_UNIT_ID;
    SET @varPlanningUnitIds = VAR_PLANNING_UNIT_IDS;
    SELECT LOCATE(",", @varPlanningUnitIds) INTO @varCommaLocation;
    IF @varEquivalencyUnitId = 0 && @varCommaLocation != 0 THEN
        SET @varPlanningUnitIds = LEFT(@varPlanningUnitIds, @varCommaLocation-1);
    END IF;
    SELECT LOCATE(",", @varProgramIds) INTO @varCommaLocation;

    IF LENGTH(@varProgramIds) <> 0 AND @varCommaLocation = 0 THEN
        
        IF @varVersionId = -1 THEN
            
            SET @varVersionId = null;
        END IF;
    ELSE
		
        SET @varVersionId = null;
    END IF;
    
    CREATE TEMPORARY TABLE `tmp_global_consumption` (
      `PROGRAM_ID` int unsigned NOT NULL DEFAULT '0' COMMENT 'Unique Id for each Program',
      `VERSION_ID` bigint unsigned DEFAULT NULL,
      `PLANNING_UNIT_ID` int unsigned DEFAULT '0' COMMENT 'Unique Id for each Planning unit',
      KEY `fk_tmp_gc_programId_idx` (`PROGRAM_ID`),
      KEY `fk_tmp_gc_versionId_idx` (`VERSION_ID`),
      KEY `fk_tmp_gc_planningUnitId_idx` (`PLANNING_UNIT_ID`)
      ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3;

    INSERT INTO tmp_global_consumption
    SELECT p.PROGRAM_ID, CAST(COALESCE(@varVersionId, p.CURRENT_VERSION_ID) AS UNSIGNED) `VERSION_ID`, pu.PLANNING_UNIT_ID 
    FROM vw_program p 
    LEFT JOIN rm_program_planning_unit ppu ON p.PROGRAM_ID=ppu.PROGRAM_ID AND ppu.ACTIVE 
    LEFT JOIN rm_planning_unit pu ON ppu.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID AND pu.ACTIVE
    WHERE 
        (LENGTH(@varProgramIds)=0 OR FIND_IN_SET(p.PROGRAM_ID,@varProgramIds)) AND 
        (LENGTH(@varRealmCountryIds)=0 OR FIND_IN_SET(p.REALM_COUNTRY_ID,@varRealmCountryIds)) AND 
        (LENGTH(@varPlanningUnitIds)=0 OR FIND_IN_SET(ppu.PLANNING_UNIT_ID, @varPlanningUnitIds)) AND 
        p.ACTIVE AND pu.PLANNING_UNIT_ID IS NOT NULL;

    SET @sqlString = "";
    SET @initialSelect = "";
    SET @groupBy = "";
    IF @varViewBy = 1 THEN 
        
        SET @initialSelect = CONCAT(@sqlString, "SELECT sma.TRANS_DATE, rc.REALM_COUNTRY_ID `ID`, c.COUNTRY_CODE `CODE`, c.LABEL_ID, c.LABEL_EN, c.LABEL_FR, c.LABEL_PR, c.LABEL_SP, SUM(IF(@varEquivalencyUnitId=0, sma.FORECASTED_CONSUMPTION_QTY, sma.FORECASTED_CONSUMPTION_QTY*pu.MULTIPLIER/eum.CONVERT_TO_EU)) `FORECASTED_CONSUMPTION`, SUM(IF(@varEquivalencyUnitId=0, sma.ACTUAL_CONSUMPTION_QTY, sma.ACTUAL_CONSUMPTION_QTY*pu.MULTIPLIER/eum.CONVERT_TO_EU)) `ACTUAL_CONSUMPTION` ");
        SET @groupBy = "GROUP BY sma.TRANS_DATE, rc.REALM_COUNTRY_ID";
    ELSE  
        
        SET @initialSelect = CONCAT(@sqlString, "SELECT sma.TRANS_DATE, p.PROGRAM_ID `ID`, p.PROGRAM_CODE `CODE`, p.LABEL_ID, p.LABEL_EN, p.LABEL_FR, p.LABEL_PR, p.LABEL_SP, SUM(IF(@varEquivalencyUnitId=0, sma.FORECASTED_CONSUMPTION_QTY, sma.FORECASTED_CONSUMPTION_QTY*pu.MULTIPLIER/eum.CONVERT_TO_EU)) `FORECASTED_CONSUMPTION`, SUM(IF(@varEquivalencyUnitId=0, sma.ACTUAL_CONSUMPTION_QTY, sma.ACTUAL_CONSUMPTION_QTY*pu.MULTIPLIER/eum.CONVERT_TO_EU)) `ACTUAL_CONSUMPTION` ");
        SET @groupBy = "GROUP BY sma.TRANS_DATE, sma.PROGRAM_ID";
    END IF;
    
    SET @sqlString = CONCAT(@sqlString, @initialSelect);
    SET @sqlString = CONCAT(@sqlString, "FROM tmp_global_consumption gc ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN rm_supply_plan_amc sma ON gc.PROGRAM_ID=sma.PROGRAM_ID AND gc.VERSION_ID=sma.VERSION_ID AND gc.PLANNING_UNIT_ID=sma.PLANNING_UNIT_ID ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN vw_program p ON sma.PROGRAM_ID=p.PROGRAM_ID ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN rm_realm_country rc ON p.REALM_COUNTRY_ID=rc.REALM_COUNTRY_ID ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN vw_country c ON c.COUNTRY_ID=rc.COUNTRY_ID ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN rm_planning_unit pu ON sma.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN rm_program_planning_unit ppu ON sma.PROGRAM_ID=ppu.PROGRAM_ID AND sma.PLANNING_UNIT_ID=ppu.PLANNING_UNIT_ID ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN rm_equivalency_unit_mapping eum ON pu.FORECASTING_UNIT_ID=eum.FORECASTING_UNIT_ID AND eum.ACTIVE AND eum.EQUIVALENCY_UNIT_ID=@varEquivalencyUnitId ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN rm_equivalency_unit eu ON eu.EQUIVALENCY_UNIT_ID=eum.EQUIVALENCY_UNIT_ID ");
    SET @sqlString = CONCAT(@sqlString, "WHERE ");
    SET @sqlString = CONCAT(@sqlString, "    sma.TRANS_DATE BETWEEN @varStartDate AND @varStopDate ");
    SET @sqlString = CONCAT(@sqlString, "    AND ppu.ACTIVE AND pu.ACTIVE ");
    SET @sqlString = CONCAT(@sqlString, @groupBy);
    SET @sqlString = CONCAT(@sqlString, " ORDER BY `CODE`, `TRANS_DATE` ");
	
    PREPARE s1 FROM @sqlString;
    EXECUTE s1;
    DROP TABLE tmp_global_consumption;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `inventoryTurns` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `inventoryTurns`(VAR_START_DATE DATE, VAR_VIEW_BY INT, VAR_PROGRAM_IDS TEXT, VAR_PRODUCT_CATEGORY_IDS TEXT, VAR_INCLUDE_PLANNED_SHIPMENTS BOOLEAN, VAR_APPROVED_SUPPLY_PLAN_ONLY TINYINT(1))
BEGIN
    
    
    
    
    
    
    
    
    
    
    

    DECLARE curProgramId INTEGER DEFAULT 0;
    DECLARE curVersionId INTEGER DEFAULT 0;
    DECLARE finished INTEGER DEFAULT 0;
    DECLARE program_cursor CURSOR FOR 
        SELECT p.PROGRAM_ID, MAX(pv.VERSION_ID) VERSION_ID
           FROM vw_program p 
           LEFT JOIN rm_program_version pv ON p.PROGRAM_ID=pv.PROGRAM_ID AND (VAR_APPROVED_SUPPLY_PLAN_ONLY=0 OR (pv.VERSION_TYPE_ID=2 AND pv.VERSION_STATUS_ID=2))
           WHERE FIND_IN_SET(p.PROGRAM_ID, VAR_PROGRAM_IDS) AND p.ACTIVE 
           GROUP BY p.PROGRAM_ID
           HAVING MAX(pv.VERSION_ID) IS NOT NULL;

	DECLARE CONTINUE HANDLER FOR NOT FOUND SET finished = 1;
    SET @startDate = VAR_START_DATE;
    SET @viewBy = VAR_VIEW_BY;
    SET @includePlannedShipments = VAR_INCLUDE_PLANNED_SHIPMENTS;
	SELECT GROUP_CONCAT(pc.PRODUCT_CATEGORY_ID) INTO @finalProductCategoryIds FROM rm_product_category pc LEFT JOIN (SELECT CONCAT(pc1.SORT_ORDER,'%') `SO` FROM rm_product_category pc1 WHERE FIND_IN_SET(pc1.PRODUCT_CATEGORY_ID, VAR_PRODUCT_CATEGORY_IDS)) pc2 ON pc.SORT_ORDER LIKE pc2.SO WHERE pc2.SO IS NOT NULL;
    
	DROP TABLE IF EXISTS tmp_inventory_turns;
	CREATE TEMPORARY TABLE `fasp`.`tmp_inventory_turns` (
		`PROGRAM_ID` INT NOT NULL,
        `PLANNING_UNIT_ID` INT NOT NULL,
        `TOTAL_CONSUMPTION` DOUBLE(16,2) NULL,
        `AVG_STOCK` DOUBLE(16,2) NULL,
        `NO_OF_MONTHS` INT NULL,
        PRIMARY KEY (`PROGRAM_ID`, `PLANNING_UNIT_ID`)
    );
    OPEN program_cursor;
    nextProgramVersionLoop: LOOP FETCH program_cursor INTO curProgramId, curVersionId;
	IF finished = 1 THEN 
		LEAVE nextProgramVersionLoop;
	END IF;
    INSERT INTO log VALUES (null, now(), CONCAT("programId:",curProgramId, ", versionId:",curVersionId));
	INSERT INTO tmp_inventory_turns 
		SELECT 
			ppu.PROGRAM_ID,
            ppu.PLANNING_UNIT_ID, 
            SUM(s2.CONSUMPTION_QTY) `TOTAL_CONSUMPTION`, 
            AVG(s2.STOCK) `AVG_STOCK`,
            COUNT(s2.CONSUMPTION_QTY) `NO_OF_MONTHS`
        FROM rm_program_planning_unit ppu 
        LEFT JOIN rm_planning_unit pu ON ppu.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID
        LEFT JOIN rm_forecasting_unit fu ON pu.FORECASTING_UNIT_ID=fu.FORECASTING_UNIT_ID
        LEFT JOIN 
			(
            SELECT 
				spa.TRANS_DATE, spa.PLANNING_UNIT_ID, 
                SUM(IF(spa.ACTUAL IS NULL, NULL, IF(spa.ACTUAL=1, spa.ACTUAL_CONSUMPTION_QTY, spa.FORECASTED_CONSUMPTION_QTY))) `CONSUMPTION_QTY`,
                SUM(IF(@includePlannedShipments, spa.CLOSING_BALANCE, spa.CLOSING_BALANCE_WPS)) `STOCK`
			FROM rm_supply_plan_amc spa WHERE spa.PROGRAM_ID=curProgramId AND spa.VERSION_ID=curVersionId AND spa.TRANS_DATE BETWEEN SUBDATE(@startDate, INTERVAL 11 MONTH) AND @startDate
            GROUP BY spa.TRANS_DATE, spa.PLANNING_UNIT_ID
            HAVING `CONSUMPTION_QTY` IS NOT NULL
		) s2 ON ppu.PLANNING_UNIT_ID=s2.PLANNING_UNIT_ID
        WHERE ppu.PROGRAM_ID=curProgramId AND ppu.ACTIVE AND pu.ACTIVE AND FIND_IN_SET(fu.PRODUCT_CATEGORY_ID, @finalProductCategoryIds)
        GROUP BY ppu.PLANNING_UNIT_ID;
	INSERT INTO log VALUES (null, now(), "Completed insert");
    END LOOP nextProgramVersionLoop;

    INSERT INTO log VALUES (null, now(), "Going to run main query");
    IF @viewBy = 1 THEN
		INSERT INTO log VALUES (null, now(), "View 1");
        SELECT 
            rc.REALM_COUNTRY_ID, c.LABEL_ID `RC_LABEL_ID`, c.LABEL_EN `RC_LABEL_EN`, c.LABEL_FR `RC_LABEL_FR`, c.LABEL_SP `RC_LABEL_SP`, c.LABEL_PR `RC_LABEL_PR`, 
            it.PROGRAM_ID, p.PROGRAM_CODE, p.LABEL_ID `P_LABEL_ID`, p.LABEL_EN `P_LABEL_EN`, p.LABEL_FR `P_LABEL_FR`, p.LABEL_SP `P_LABEL_SP`, p.LABEL_PR `P_LABEL_PR`, 
            it.PLANNING_UNIT_ID, pu.LABEL_ID `PU_LABEL_ID`, pu.LABEL_EN `PU_LABEL_EN`, pu.LABEL_FR `PU_LABEL_FR`, pu.LABEL_SP `PU_LABEL_SP`, pu.LABEL_PR `PU_LABEL_PR`, 
            pc.PRODUCT_CATEGORY_ID, pc.LABEL_ID `PC_LABEL_ID`, pc.LABEL_EN `PC_LABEL_EN`, pc.LABEL_FR `PC_LABEL_FR`, pc.LABEL_SP `PC_LABEL_SP`, pc.LABEL_PR `PC_LABEL_PR`, 
            it.TOTAL_CONSUMPTION, it.AVG_STOCK, it.NO_OF_MONTHS, it.TOTAL_CONSUMPTION/it.AVG_STOCK `INVENTORY_TURNS`,
            ppu.REORDER_FREQUENCY_IN_MONTHS, ppu.MIN_MONTHS_OF_STOCK, rm.TOTAL_MONTHS_OF_PLANNED_CONSUMPTION, 144/(rm.TOTAL_MONTHS_OF_PLANNED_CONSUMPTION+ppu.MIN_MONTHS_OF_STOCK*12) `PLANNED_INVENTORY_TURNS`
        FROM tmp_inventory_turns it 
        LEFT JOIN vw_program p ON it.PROGRAM_ID=p.PROGRAM_ID
        LEFT JOIN rm_realm_country rc ON p.REALM_COUNTRY_ID=rc.REALM_COUNTRY_ID
        LEFT JOIN vw_country c ON rc.COUNTRY_ID=c.COUNTRY_ID
        LEFT JOIN vw_planning_unit pu ON it.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID
        LEFT JOIN rm_program_planning_unit ppu ON p.PROGRAM_ID=ppu.PROGRAM_ID AND pu.PLANNING_UNIT_ID=ppu.PLANNING_UNIT_ID
        LEFT JOIN rm_forecasting_unit fu ON pu.FORECASTING_UNIT_ID=fu.FORECASTING_UNIT_ID
        LEFT JOIN vw_product_category pc ON fu.PRODUCT_CATEGORY_ID=pc.PRODUCT_CATEGORY_ID
        LEFT JOIN ap_reorder_master rm ON ppu.REORDER_FREQUENCY_IN_MONTHS=rm.NO_OF_MONTHS_FOR_REORDER
        ORDER BY c.LABEL_EN, p.PROGRAM_CODE, pu.LABEL_EN
        ;
    ELSEIF @viewBy = 2 THEN
		INSERT INTO log VALUES (null, now(), "View 2");
        SELECT 
            rc.REALM_COUNTRY_ID, c.LABEL_ID `RC_LABEL_ID`, c.LABEL_EN `RC_LABEL_EN`, c.LABEL_FR `RC_LABEL_FR`, c.LABEL_SP `RC_LABEL_SP`, c.LABEL_PR `RC_LABEL_PR`, 
            it.PROGRAM_ID, p.PROGRAM_CODE, p.LABEL_ID `P_LABEL_ID`, p.LABEL_EN `P_LABEL_EN`, p.LABEL_FR `P_LABEL_FR`, p.LABEL_SP `P_LABEL_SP`, p.LABEL_PR `P_LABEL_PR`, 
            it.PLANNING_UNIT_ID, pu.LABEL_ID `PU_LABEL_ID`, pu.LABEL_EN `PU_LABEL_EN`, pu.LABEL_FR `PU_LABEL_FR`, pu.LABEL_SP `PU_LABEL_SP`, pu.LABEL_PR `PU_LABEL_PR`, 
            pc.PRODUCT_CATEGORY_ID, pc.LABEL_ID `PC_LABEL_ID`, pc.LABEL_EN `PC_LABEL_EN`, pc.LABEL_FR `PC_LABEL_FR`, pc.LABEL_SP `PC_LABEL_SP`, pc.LABEL_PR `PC_LABEL_PR`, 
            it.TOTAL_CONSUMPTION, it.AVG_STOCK, it.NO_OF_MONTHS, it.TOTAL_CONSUMPTION/it.AVG_STOCK `INVENTORY_TURNS`,
            ppu.REORDER_FREQUENCY_IN_MONTHS, ppu.MIN_MONTHS_OF_STOCK, rm.TOTAL_MONTHS_OF_PLANNED_CONSUMPTION, 144/(rm.TOTAL_MONTHS_OF_PLANNED_CONSUMPTION+ppu.MIN_MONTHS_OF_STOCK*12) `PLANNED_INVENTORY_TURNS`
        FROM tmp_inventory_turns it 
        LEFT JOIN vw_program p ON it.PROGRAM_ID=p.PROGRAM_ID
        LEFT JOIN rm_realm_country rc ON p.REALM_COUNTRY_ID=rc.REALM_COUNTRY_ID
        LEFT JOIN vw_country c ON rc.COUNTRY_ID=c.COUNTRY_ID
        LEFT JOIN vw_planning_unit pu ON it.PLANNING_UNIT_ID=pu.PLANNING_UNIT_ID
        LEFT JOIN rm_program_planning_unit ppu ON p.PROGRAM_ID=ppu.PROGRAM_ID AND pu.PLANNING_UNIT_ID=ppu.PLANNING_UNIT_ID
        LEFT JOIN rm_forecasting_unit fu ON pu.FORECASTING_UNIT_ID=fu.FORECASTING_UNIT_ID
        LEFT JOIN vw_product_category pc ON fu.PRODUCT_CATEGORY_ID=pc.PRODUCT_CATEGORY_ID
        LEFT JOIN ap_reorder_master rm ON ppu.REORDER_FREQUENCY_IN_MONTHS=rm.NO_OF_MONTHS_FOR_REORDER
        ORDER BY pc.LABEL_EN, p.PROGRAM_CODE, pu.LABEL_EN
        ;
    END IF;
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
/*!50003 SET collation_connection  = @saved_col_connection */ ;
/*!50003 DROP PROCEDURE IF EXISTS `procurementAgentShipmentReport` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb3 */ ;
/*!50003 SET character_set_results = utf8mb3 */ ;
/*!50003 SET collation_connection  = utf8mb3_general_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`faspUser`@`localhost` PROCEDURE `procurementAgentShipmentReport`(VAR_START_DATE DATE, VAR_STOP_DATE DATE, VAR_PROCUREMENT_AGENT_IDS VARCHAR(255), VAR_PROGRAM_ID INT, VAR_VERSION_ID INT, VAR_PLANNING_UNIT_IDS TEXT, VAR_INCLUDE_PLANNED_SHIPMENTS TINYINT)
BEGIN
    
    
    
    
    
    
    
    
    
    
    
    
    
    
    SET @programId = VAR_PROGRAM_ID;
    SET @versionId = VAR_VERSION_ID;
    IF @versionId = -1 THEN
	SELECT MAX(pv.VERSION_ID) INTO @versionId FROM rm_program_version pv WHERE pv.PROGRAM_ID=@programId;
    END IF;
    SET @startDate = CONCAT(VAR_START_DATE,' 00:00:00');
    SET @stopDate = CONCAT(VAR_STOP_DATE, ' 23:59:59');
    SET @includePlannedShipments = VAR_INCLUDE_PLANNED_SHIPMENTS;
    SET @planningUnitIds = VAR_PLANNING_UNIT_IDS;
    SET @procurementAgentIds = VAR_PROCUREMENT_AGENT_IDS;

    SELECT 
    	pa.PROCUREMENT_AGENT_ID, pa.PROCUREMENT_AGENT_CODE, pa.LABEL_ID `PROCUREMENT_AGENT_LABEL_ID`, pa.LABEL_EN `PROCUREMENT_AGENT_LABEL_EN`, pa.LABEL_FR `PROCUREMENT_AGENT_LABEL_FR`, pa.LABEL_SP `PROCUREMENT_AGENT_LABEL_SP`, pa.LABEL_PR `PROCUREMENT_AGENT_LABEL_PR`, 
    	pu.PLANNING_UNIT_ID, pu.LABEL_ID `PLANNING_UNIT_LABEL_ID`, pu.LABEL_EN `PLANNING_UNIT_LABEL_EN`, pu.LABEL_FR `PLANNING_UNIT_LABEL_FR`, pu.LABEL_SP `PLANNING_UNIT_LABEL_SP`, pu.LABEL_PR `PLANNING_UNIT_LABEL_PR`, 
    	SUM(st.SHIPMENT_QTY) QTY, SUM(st.PRODUCT_COST*s.CONVERSION_RATE_TO_USD) `PRODUCT_COST`, SUM(st.FREIGHT_COST*s.CONVERSION_RATE_TO_USD) `FREIGHT_COST`, SUM(st.FREIGHT_COST*s.CONVERSION_RATE_TO_USD)/SUM(st.PRODUCT_COST*s.CONVERSION_RATE_TO_USD)*100 `FREIGHT_PERC` 
    FROM 
    	(
    	SELECT 
            s.PROGRAM_ID, s.SHIPMENT_ID, s.CONVERSION_RATE_TO_USD, MAX(st.VERSION_ID) MAX_VERSION_ID 
    	FROM rm_shipment s 
    	LEFT JOIN rm_shipment_trans st ON s.SHIPMENT_ID=st.SHIPMENT_ID 
    	WHERE 
            s.PROGRAM_ID=@programId 
            AND st.VERSION_ID<=@versionId 
            AND st.SHIPMENT_TRANS_ID IS NOT NULL 
    	GROUP BY s.SHIPMENT_ID 
    ) AS s 
    LEFT JOIN rm_shipment s1 ON s.SHIPMENT_ID=s1.SHIPMENT_ID 
    LEFT JOIN rm_shipment_trans st ON s.SHIPMENT_ID=st.SHIPMENT_ID AND s.MAX_VERSION_ID=st.VERSION_ID 
    LEFT JOIN vw_procurement_agent pa ON st.PROCUREMENT_AGENT_ID=pa.PROCUREMENT_AGENT_ID 
    LEFT JOIN vw_planning_unit pu ON st.PLANNING_UNIT_ID = pu.PLANNING_UNIT_ID 
    LEFT JOIN rm_program_planning_unit ppu ON st.PLANNING_UNIT_ID = ppu.PLANNING_UNIT_ID AND s1.PROGRAM_ID=ppu.PROGRAM_ID 
    WHERE 
    	st.ACTIVE AND ppu.ACTIVE AND pu.ACTIVE  AND st.ACCOUNT_FLAG 
    	AND st.SHIPMENT_STATUS_ID != 8 
    	AND ((@includePlannedShipments=0 && st.SHIPMENT_STATUS_ID in (3,4,5,6,7)) OR @includePlannedShipments=1) 
    	AND COALESCE(st.RECEIVED_DATE, st.EXPECTED_DELIVERY_DATE) BETWEEN @startDate AND @stopDate 
	AND (LENGTH(@planningUnitIds)=0 OR FIND_IN_SET(st.PLANNING_UNIT_ID, @planningUnitIds)) 
       	AND (LENGTH(@procurementAgentIds)=0 OR FIND_IN_SET(st.PROCUREMENT_AGENT_ID, @procurementAgentIds)) 
    GROUP BY st.PROCUREMENT_AGENT_ID, st.PLANNING_UNIT_ID;
    
END ;;
DELIMITER ;
/*!50003 SET sql_mode              = @saved_sql_mode */ ;
/*!50003 SET character_set_client  = @saved_cs_client */ ;
/*!50003 SET character_set_results = @saved_cs_results */ ;
