    SET @sqlString = CONCAT(@sqlString, "   SUM(IFNULL(s1.`ONHOLD_COST`,0)) `ONHOLD_COST`  ");
    SET @sqlString = CONCAT(@sqlString, "FROM mn  ");
    SET @sqlString = CONCAT(@sqlString, "LEFT JOIN  ");
    SET @sqlString = CONCAT(@sqlString, "   (  ");
