    SET @sqlString = CONCAT(@sqlString, "       IF(st.SHIPMENT_STATUS_ID=9, (IFNULL(st.PRODUCT_COST,0) + IFNULL(st.FREIGHT_COST,0)) * s.CONVERSION_RATE_TO_USD, 0) `ONHOLD_COST`,  ");
    SET @sqlString = CONCAT(@sqlString, "       st.SHIPMENT_ID  ");
